#include <stdio.h>

void swap(int *a, int *b)
{
    int temp = *a;
    *a = *b;
    *b = temp;
}

int main(void)
{
    int x = 3, y = 8;
    swap(&x, &y);
    printf("%d %d\n", x, y);
    return 0;
}

#include <stdio.h>

int add_small(int a, int b, int *out)
{
    if (out == NULL || a < 0 || a > 100 || b < 0 || b > 100) { return 0; }
    *out = a + b;
    return 1;
}

int main(void)
{
    int out = 99;
    int ok = add_small(-1, 2, &out);
    printf("%d %d\n", ok, out);
    return 0;
}

#include <stdio.h>

void set_zero(int *p)
{
    *p = 0;
}

int main(void)
{
    int x = 5;
    set_zero(&x);
    printf("%d\n", x);
    return 0;
}

